package org.jsoup.helper;

import org.jsoup.Connection;
import org.jsoup.helper.UrlBuilder;
import org.junit.Test;

import java.io.UnsupportedEncodingException;
import java.net.MalformedURLException;
import java.net.URL;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class UrlBuilderTest {

	@Test
	public void constructorTest_ValidInputUrl() throws MalformedURLException {
		URL validInputUrl = new URL("https://google.com");
		UrlBuilder urlBuilder = new UrlBuilder(validInputUrl);

		assertNotNull(urlBuilder);
	}

	@Test(expected = NullPointerException.class)
	public void constructorTest_NullInputUrl() {
		new UrlBuilder(null);
	}

	@Test
	public void buildTest_ValidUrlBuilder() throws MalformedURLException {
		URL validInputUrl = new URL("https://google.com");
		UrlBuilder urlBuilder = new UrlBuilder(validInputUrl);

		URL outputUrl = urlBuilder.build();

		assertNotNull(outputUrl);
		assertEquals("https://google.com", outputUrl.toString());
	}

	@Test
	public void appendKeyValTest_ValidKeyVal() throws UnsupportedEncodingException, MalformedURLException {
		URL validInputUrl = new URL("https://google.com");
		UrlBuilder urlBuilder = new UrlBuilder(validInputUrl);
		Connection.KeyVal validKeyVal = Connection.KeyVal.create("key", "value");

		urlBuilder.appendKeyVal(validKeyVal);

		URL outputUrl = urlBuilder.build();

		assertNotNull(outputUrl);
		assertEquals("https://google.com?key=value", outputUrl.toString());
	}

	@Test(expected = UnsupportedEncodingException.class)
	public void appendKeyValTest_InvalidKeyVal() throws UnsupportedEncodingException, MalformedURLException {
		URL validInputUrl = new URL("https://google.com");
		UrlBuilder urlBuilder = new UrlBuilder(validInputUrl);
		Connection.KeyVal invalidKeyVal = Connection.KeyVal.create("key", "€");

		urlBuilder.appendKeyVal(invalidKeyVal);
	}

	@Test(expected = NullPointerException.class)
	public void appendKeyValTest_NullKeyVal() throws UnsupportedEncodingException, MalformedURLException {
		URL validInputUrl = new URL("https://google.com");
		UrlBuilder urlBuilder = new UrlBuilder(validInputUrl);

		urlBuilder.appendKeyVal(null);
	}

}
```
